// Demo workflow: fetch the top Hacker News stories (zero credentials).
// It exists so a fresh install has something real on the dashboard — it
// produces executions, a workflow-map node and a form button. It does not
// publish a feed: the po11y server owns every feed, from its own store.
const ids = await this.helpers.httpRequest({ url: 'https://hacker-news.firebaseio.com/v0/topstories.json', json: true });
const stories = [];
for (const id of ids.slice(0, 10)) {
  const it = await this.helpers.httpRequest({ url: `https://hacker-news.firebaseio.com/v0/item/${id}.json`, json: true });
  if (!it || !it.title) continue;
  stories.push({
    ts: new Date((it.time || 0) * 1000).toISOString(),
    title: it.title,
    message: `HN · ${it.score || 0} upvotes`,
    status: 'info',
    link: it.url || `https://news.ycombinator.com/item?id=${id}`,
  });
}
return [{ json: { stories } }];
